INSERT INTO `openings` (`jobid`, `code`, `jobTitle`, `departmentId`, `openingCount`, `requiredSkills`, `minExperience`, `jobDescription`, `isActive`, `jobOpeningUrl`, `createdAt`, `updatedAt`, `deletedAt`) VALUES (3, 'DM-001', 'Digital Marketing Manager', 3, 3, 'A proactive, ownership-driven professional with a growth mindset. A balance of creativity, analytical thinking, and execution. Someone who understands customer behavior and can translate insights into effective campaigns. A collaborative team player who t', 4, '', 1, 'https://staging.khosocial.com/cif-form?jobid=3', '2026-10-26T06:47:24.000Z', '2026-10-26T06:47:33.000Z', NULL);
INSERT INTO `openings` (`jobid`, `code`, `jobTitle`, `departmentId`, `openingCount`, `requiredSkills`, `minExperience`, `jobDescription`, `isActive`, `jobOpeningUrl`, `createdAt`, `updatedAt`, `deletedAt`) VALUES (4, 'DM-002', 'Digital Marketing Executive', 3, 1, 'Social Media Marketing,Performance Marketing,Communication', 1, 'Job Description: Digital Marketing Executive\n\nCompany: Kho Social\nDepartment: Marketing\nExperience: 1–3 Years\nLocation:Coimbatore\nEmployment Type: Full-time\n\nAbout Kho\n\nKho is looking for a creative, enthusiastic, and result-oriented Digital Marketing Executive to support our digital marketing initiatives, strengthen our online presence, engage with our target audience, and contribute to business growth.\n\nJob Overview\n\nThe Digital Marketing Executive will be responsible for executing digital marketing campaigns, managing social media platforms, supporting performance marketing activities, improving website visibility, and tracking campaign performance.\n\nKey Responsibilities\n1. Social Media Marketing\nManage and maintain social media platforms, including Instagram, Facebook, LinkedIn, and YouTube.\nPlan and execute social media content calendars.\nCoordinate with designers, content creators, and influencers to develop engaging creatives and campaigns.\nMonitor audience engagement, comments, messages, and social media performance.\n2. Performance Marketing\nAssist in planning, executing, and optimizing campaigns on Meta Ads and Google Ads.\nMonitor advertising budgets, campaign performance, reach, clicks, leads, and conversions.\nSupport A/B testing of ad creatives, copy, and audience targeting.\nTrack campaign effectiveness and suggest improvements.\n3. Search Engine Optimization (SEO)\nConduct keyword research and competitor analysis.\nImplement basic on-page and off-page SEO activities.\nOptimize website content and meta descriptions to improve search visibility.\nMonitor organic traffic and keyword performance using Google Search Console and analytics tools.\n4. Content Marketing\nCreate engaging captions, ad copy, and digital marketing content.\nAssist in developing blogs, email campaigns, landing pages, and promotional content.\nEnsure consistency in brand voice and communication across digital platforms.\nCoordinate with the creative team for marketing materials.\n5. Analytics and Reporting\nTrack website traffic, social media engagement, and digital campaign performance.\nPrepare weekly and monthly marketing reports.\nUse tools such as Google Analytics 4, Google Search Console, and platform insights.\nIdentify trends and recommend improvements based on performance data.\n6. Campaign Coordination\nSupport the execution of product launches, promotional campaigns, and brand awareness initiatives.\nCoordinate with internal teams, agencies, and external vendors.\nEnsure campaigns are delivered on time and aligned with marketing objectives.\nSkills and Qualifications\nBachelor\'s degree in Marketing, Business Administration, Communications, or a related field.\n1–3 years of experience in digital marketing or a similar role.\nBasic to intermediate knowledge of social media marketing, Meta Ads, Google Ads, and SEO.\nFamiliarity with Canva or other creative tools is an advantage.\nKnowledge of Google Analytics 4 and Google Search Console.\nGood written and verbal communication skills.\nStrong organizational skills, creativity, and attention to detail.\nAbility to work collaboratively and manage multiple tasks.\nKey Performance Indicators (KPIs)\nSocial media reach, engagement, and follower growth.\nWebsite traffic and organic search performance.\nCampaign execution and lead generation.\nAdvertising performance and conversion rates.\nContent delivery within deadlines.\nImprovement in digital campaign efficiency.\nPreferred Candidate Profile\nCreative, proactive, and eager to learn.\nInterested in digital trends, content formats, and online consumer behavior.\nComfortable working in a fast-paced environment.\nAble to combine creative ideas with data-driven decision-making.\nHow to Apply\n\nInterested candidates can share their resume along with relevant work samples or campaign portfolios at [Insert Email Address].\n\nJoin Kho Social and be part of our digital growth journey!', 1, 'https://staging.khosocial.com/cif-form?jobid=4', '2026-10-26T06:51:45.000Z', '2026-10-26T06:51:45.000Z', NULL);
INSERT INTO `openings` (`jobid`, `code`, `jobTitle`, `departmentId`, `openingCount`, `requiredSkills`, `minExperience`, `jobDescription`, `isActive`, `jobOpeningUrl`, `createdAt`, `updatedAt`, `deletedAt`) VALUES (5, 'DE-001', 'Designs Manager', 6, 1, 'Creative Direction: Ability to develop creative concepts, visual strategies, and design directions aligned with brand objectives.  Graphic Design Expertise: Strong proficiency in Adobe Photoshop and Adobe Illustrator; working knowledge of Adobe InDesign a', 5, 'Job Description: Designs Manager\n\nCompany: Kho Social LLP\nDepartment: Designs\nExperience: 5–8 Years\nEmployment Type: Full-time\nLocation: Coimbatore, Tamil Nadu\n\nJob Overview\n\nKho Social LLP is looking for a creative, strategic, and detail-oriented Designs Manager to lead our design team and oversee the development of impactful visual communication across digital and offline platforms.\n\nThe ideal candidate will have strong design expertise, excellent creative direction skills, and the ability to translate brand objectives and marketing strategies into compelling visual experiences. This role requires leadership, innovation, and collaboration with marketing and other internal teams to maintain brand consistency and deliver high-quality creative outputs.\n\nKey Responsibilities\n1. Creative Direction & Design Strategy\nDevelop and execute creative design strategies aligned with the company\'s brand identity and business objectives.\nEstablish visual guidelines, design standards, and creative direction across campaigns.\nEnsure consistency in branding, typography, color palettes, layouts, and visual storytelling.\nDrive creative innovation and explore new design trends, formats, and concepts.\n2. Team Leadership & Management\nLead, mentor, and manage the design team to ensure high-quality creative delivery.\nAllocate projects, manage workloads, and prioritize tasks based on business requirements.\nReview designs and provide constructive feedback to improve creative quality.\nBuild a collaborative, productive, and innovative design culture.\n3. Design Execution & Quality Control\nOversee the creation of social media creatives, digital advertisements, campaign visuals, presentations, brochures, and other marketing collaterals.\nReview and approve design outputs before final delivery.\nEnsure all creative assets meet brand guidelines, campaign objectives, and quality standards.\nManage multiple projects simultaneously while ensuring timely execution.\n4. Brand Identity & Campaign Development\nDevelop creative concepts for brand campaigns, product launches, promotional activities, and special projects.\nCollaborate with the marketing and digital marketing teams to develop integrated campaign visuals.\nEnsure designs effectively communicate the brand\'s message and resonate with the target audience.\nContribute to brand positioning through strong visual identity and creative storytelling.\n5. Cross-Functional Collaboration\nWork closely with marketing, content, performance marketing, and business teams to understand campaign requirements.\nTranslate creative briefs into clear design directions and actionable deliverables.\nCoordinate with external agencies, freelancers, photographers, and production partners when required.\nEnsure smooth communication and alignment between creative and business teams.\n6. Project & Workflow Management\nEstablish efficient design workflows, review processes, and approval systems.\nManage project timelines, creative briefs, revisions, and delivery schedules.\nMonitor team productivity and ensure projects are completed within agreed timelines.\nIdentify opportunities to improve design processes and operational efficiency.\n7. Trends, Tools & Innovation\nStay updated with emerging design trends, creative technologies, and industry best practices.\nExplore AI-powered design tools and innovative creative workflows where relevant.\nEncourage experimentation with new visual formats, motion graphics, and digital experiences.\nMaintain a strong understanding of design requirements across social media and marketing platforms.\nRequired Skills & Qualifications\n5–8 years of professional experience in graphic design, creative design, or visual communication, including team leadership or creative management experience.\nStrong proficiency in Adobe Photoshop and Adobe Illustrator.\nWorking knowledge of Adobe InDesign, Figma, and other relevant design tools.\nUnderstanding of branding, typography, color theory, composition, and visual hierarchy.\nExperience in developing brand identities, campaign creatives, and marketing collaterals.\nStrong creative direction, conceptualization, and visual storytelling skills.\nExcellent team management, communication, and stakeholder coordination abilities.\nStrong project management skills with the ability to handle multiple priorities.\nHigh attention to detail and a commitment to design quality.\nAbility to work in a fast-paced environment and meet tight deadlines.\nPreferred Skills\nExperience with motion graphics and video editing tools such as Adobe After Effects and Premiere Pro.\nFamiliarity with AI-powered creative tools and design automation.\nExperience working with digital marketing, advertising, lifestyle, retail, or consumer brands.\nUnderstanding of social media content formats, digital campaigns, and performance-driven creative requirements.\nExperience managing external creative partners and production vendors.\nKey Performance Indicators (KPIs)\nQuality, originality, and consistency of creative outputs.\nTimely delivery of design projects and campaigns.\nTeam productivity and effective workload management.\nAdherence to brand guidelines and creative standards.\nEfficiency of design review and approval processes.\nStakeholder satisfaction and collaboration.\nContinuous improvement in creative workflows and output quality.\nIdeal Candidate Profile\n\nWe are looking for a creative leader who combines strong design fundamentals with strategic thinking and people management skills. The ideal candidate should be proactive, organized, collaborative, and passionate about building compelling visual identities while inspiring a team to deliver exceptional creative work.\n\nHow to Apply\n\nInterested candidates can share their updated resume and portfolio showcasing relevant design projects, brand identities, and creative campaigns at [Insert Email Address].\n\nJoin Kho Social LLP and lead the next chapter of our creative journey!', 1, 'https://staging.khosocial.com/cif-form?jobid=5', '2026-10-26T07:52:22.000Z', '2026-10-26T07:52:22.000Z', NULL);
